export const SCRIPT = "\ndocument.documentElement.classList.add('js');\nconst tabs=[...document.querySelectorAll('.tab')];\nconst panels=[...document.querySelectorAll('.panel')];\nconst prefersReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;\n\nfunction countUp(el){\n  if(prefersReduced||el.dataset.done){el.innerHTML=el.dataset.count+(el.dataset.suffix||'');return;}el.dataset.done=1;\n  const target=+el.dataset.count, suf=el.dataset.suffix||'', dur=1100, t0=performance.now();\n  (function step(now){\n    const p=Math.min(1,(now-t0)/dur), e=1-Math.pow(1-p,3);\n    el.innerHTML=Math.round(target*e)+suf;\n    if(p<1)requestAnimationFrame(step);\n  })(t0);\n}\n\nconst io=new IntersectionObserver((es)=>{es.forEach(e=>{\n  if(e.isIntersecting){\n    e.target.classList.add('in');\n    e.target.querySelectorAll&&e.target.querySelectorAll('[data-count]').forEach(countUp);\n    if(e.target.dataset&&e.target.dataset.count)countUp(e.target);\n    io.unobserve(e.target);\n  }})},{threshold:.14,rootMargin:'0px 0px -7% 0px'});\n\nfunction observeReveals(scope){\n  (scope||document).querySelectorAll('.reveal:not(.in)').forEach(el=>{const r=el.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0)el.classList.add('in');});\n  (scope||document).querySelectorAll('.reveal:not(.in)').forEach(el=>io.observe(el));\n  (scope||document).querySelectorAll('.stat:not(.in)').forEach(el=>io.observe(el));\n  (scope||document).querySelectorAll('[data-count]').forEach(el=>io.observe(el));\n}\nfunction show(key){\n  tabs.forEach(t=>t.classList.toggle('active',t.dataset.tab===key));\n  panels.forEach(p=>{p.hidden = p.dataset.panel!==key;});\n  const active=document.querySelector('#panel-'+key);\n  if(active){\n    active.querySelectorAll('.reveal,.stat').forEach(el=>el.classList.remove('in'));\n    \n    requestAnimationFrame(()=>observeReveals(active));\n  }\n}\ntabs.forEach(t=>t.addEventListener('click',()=>{\n  show(t.dataset.tab);\n  document.querySelector('.tabs').scrollIntoView({behavior:'smooth',block:'start'});\n}));\n\nconst topbar=document.getElementById('topbar');\naddEventListener('scroll',()=>{topbar.classList.toggle('scrolled',scrollY>10);topbar.classList.toggle('shrink',scrollY>80);},{passive:true});\n\n// subtle hero parallax on the three portraits\nconst agents=[...document.querySelectorAll('.team .agent')];\nif(!prefersReduced){\n  let ticking=false;\n  addEventListener('scroll',()=>{\n    if(ticking)return;ticking=true;\n    requestAnimationFrame(()=>{\n      const y=scrollY;\n      \n      ticking=false;\n    });\n  },{passive:true});\n}\n\nconst nt=document.getElementById('navtoggle');nt&&nt.addEventListener('click',()=>{const o=topbar.classList.toggle('open');nt.setAttribute('aria-expanded',o);});\ndocument.querySelectorAll('#topnav a,#topnav button').forEach(a=>a.addEventListener('click',()=>{topbar.classList.remove('open');nt&&nt.setAttribute('aria-expanded','false');}));\ndocument.querySelectorAll('.agent-photo').forEach(a=>a.addEventListener('touchstart',()=>{document.querySelectorAll('.agent-photo.tap').forEach(x=>x!==a&&x.classList.remove('tap'));a.classList.toggle('tap');},{passive:true}));\ndocument.addEventListener('click',e=>{document.querySelectorAll('details.callmenu[open]').forEach(d=>{if(!d.contains(e.target)||e.target.closest('.callpop a'))d.removeAttribute('open');});});\ndocument.querySelectorAll('.rv-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.rv-tab').forEach(x=>{const on=x===b;x.classList.toggle('on',on);x.setAttribute('aria-selected',on);});document.querySelectorAll('.rv-panel').forEach(p=>{p.hidden=p.dataset.rvp!==b.dataset.rv;});}));\n// essential page init \u2014 panels + reveals\nshow('buy');\nobserveReveals(document);\n\n/* =====================================================================\n   LEAD EMAIL SETUP  (Web3Forms)\n   ---------------------------------------------------------------------\n   1. Go to https://web3forms.com  -> enter the delivery email -> you'll\n      get an Access Key by email. Paste it below as ACCESS_KEY.\n   2. The lead emails go to whatever address you verified, plus everyone\n      listed in TEAM_EMAILS (added as CC so all three of you get every lead).\n   3. That's it. No server needed.\n   ===================================================================== */\nconst WEB3FORMS = {\n  ACCESS_KEY: \"e4a2a96d-b64e-4440-8863-903597679611\",\n  TEAM_EMAILS: [\n    \"Lucas@therealtyadvisors.com\",\n    \"Nickbarberio@therealtyadvisors.com\",\n    \"jeff@therealtyadvisors.com\"\n  ]\n};\n\nconst INTENT_LABEL = {buy:\"Buyer Lead\", sell:\"Seller Lead\", rent:\"Renter Lead\", rentout:\"Landlord Lead\"};\nconst FIELD_LABEL = {\n  name:\"Full Name\", email:\"Email\", phone:\"Phone\", address:\"Property Address\",\n  budget:\"Budget\", rent:\"Target Rent\", timeline:\"Timeline\", showable:\"When Showable\",\n  preapproved:\"Pre-Approved\", status:\"Rent / Own\", findus:\"How They Found Us\", notes:\"Notes\"\n};\n\nasync function sendLead(intent, data){\n  if(WEB3FORMS.ACCESS_KEY.startsWith(\"REPLACE_\")){\n    // Not configured yet \u2014 log and succeed so the form still works in preview.\n    console.warn(\"Web3Forms not configured. Lead captured locally:\", intent, data);\n    return new Promise(r=>setTimeout(r,500));\n  }\n  // Build a readable summary so the email body reads cleanly.\n  const lines=Object.keys(data)\n    .filter(k=>data[k]&&data[k].trim())\n    .map(k=>`${FIELD_LABEL[k]||k}: ${data[k]}`)\n    .join(\"\\n\");\n\n  const payload={\n    access_key: WEB3FORMS.ACCESS_KEY,\n    subject: `New ${INTENT_LABEL[intent]||\"Lead\"} \u2014 DynamicDuoLI`,\n    from_name: \"DynamicDuoLI Website\",\n    cc: WEB3FORMS.TEAM_EMAILS.join(\",\"),\n    // friendly reply-to so you can reply straight to the lead:\n    replyto: data.email||\"\",\n    \"Lead Type\": INTENT_LABEL[intent]||intent,\n    ...data,\n    message: `New ${INTENT_LABEL[intent]||\"lead\"} from the website:\\n\\n${lines}`\n  };\n\n  const res=await fetch(\"https://api.web3forms.com/submit\",{\n    method:\"POST\",\n    headers:{\"Content-Type\":\"application/json\", Accept:\"application/json\"},\n    body:JSON.stringify(payload)\n  });\n  const out=await res.json();\n  if(!out.success) throw new Error(out.message||\"Submit failed\");\n  return out;\n}\ndocument.querySelectorAll('.lead-form').forEach(form=>{\n  form.addEventListener('submit',async e=>{\n    e.preventDefault();\n    const status=form.querySelector('.form-status');\n    const btn=form.querySelector('.submit');\n    status.className='form-status';status.textContent='';\n    let ok=true;\n    form.querySelectorAll('[required]').forEach(el=>{el.classList.remove('invalid');if(!el.value.trim()){el.classList.add('invalid');ok=false;}});\n    const email=form.querySelector('[name=email]');\n    if(email&&email.value&&!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email.value)){email.classList.add('invalid');ok=false;}\n    if(!ok){status.className='form-status err';status.textContent='Please fill in the required fields.';return;}\n    const data={};new FormData(form).forEach((v,k)=>data[k]=v);\n    btn.disabled=true;const orig=btn.innerHTML;btn.innerHTML='Sending\u2026';\n    try{await sendLead(form.dataset.intent,data);form.reset();\n      status.className='form-status ok';status.textContent='Got it \u2014 we will be in touch shortly.';\n    }catch(err){status.className='form-status err';status.textContent='Something went wrong. Please call or text us directly.';\n    }finally{btn.disabled=false;btn.innerHTML=orig;}\n  });\n});\n\n// Prefill the buyer form when arriving from a listing's \"Interested\" button.\n(function(){\n  const q=new URLSearchParams(location.search);const it=q.get('interest');\n  if(!it&&location.hash!=='#panel-buy')return;\n  show('buy');\n  const form=document.querySelector('#panel-buy .lead-form');\n  if(it&&form){const n=form.querySelector('[name=notes]');if(n&&!n.value){n.textContent='Interested in '+it;n.value='Interested in '+it;}}\n  setTimeout(()=>{const el=document.getElementById('panel-buy');if(el)el.scrollIntoView({block:'start'});},250);\n})();\n";

export const HERO_META = '<div><b data-count="144" data-suffix="+">144+</b><span>Homes Sold</span></div>';
